#include<bits/stdc++.h>
using namespace std;
#define int long long
#define itn int
signed main() {
    ios::sync_with_stdio(0);
    cin.tie(0),cout.tie(0);
    auto solve=[&]() {
        int m,n;cin>>n>>m;
        string sn,sm;cin>>sn>>sm;
        sn.insert(sn.begin(), ' ');
        sm.insert(sm.begin(), ' ');
        auto calc = [](int n, int m, const string& sn, const string& sm) {
            int mxm = -1, last_q = -1, active = 0;
            vector<int> cnt(m + 2, 0);
            for (int i = 1; i <= m; i++) {
                if (sm[i] == 'W') {
                    if (last_q != -1) {
                        cnt[i - last_q]++;
                    }
                    last_q = i;
                    mxm = i;
                    active++;
                }
            }
            int tmp = 0, flag = 0, cur_union = 0;
            for (int i = 1; i <= n; i++) {
                if (!flag) {
                    cur_union += active;
                    if (i <= m) active -= cnt[i];
                }
                if (sn[i] == 'R') {
                    tmp++;
                    if (!flag) {
                        cout << cur_union + 1 << ' ';
                    } else {
                        int p = i - tmp; 
                        int R = max(mxm == -1 ? 0LL : i - 1 + mxm, p + m);
                        cout << R - p + 1 << ' ';
                    }
                } else {
                    tmp = 0;
                    flag = 1;
                }
            }
            cout << '\n';
        };
        calc(n, m, sn, sm);
        calc(m, n, sm, sn);
    };
    int t;
    for(cin>>t;t;t--)
    solve();
    return 0;
}

